document.addEventListener("DOMContentLoaded", () => {
import("./api.js")
  .then((api) => {
    console.log("test: api.js shares " + Object.keys(api).sort().join(", "));
    console.log("test: SHIPS_URL is " + api.SHIPS_URL);
    console.log("test: CREW_URL is " + api.CREW_URL);
    return api.getJson(api.CREW_URL);
  })
  .then((crew) => console.log("test: getJson gave " + JSON.stringify(crew)))
  .catch((error) => console.log("test: failed " + error.message));
});

